input.old_string:
# Parse arguments
RUN_LIVE=false
RUN_LAYER=""
RUN_ALL=false

while [ $# -gt 0 ]; do
  case "$1" in
    --live) RUN_LIVE=true; shift ;;
    --layer) RUN_LAYER="$2"; shift 2 ;;
    --integration) RUN_LAYER="7"; shift ;;
    --all) RUN_ALL=true; RUN_LIVE=true; shift ;;
    --verbose) export VERBOSE=true; shift ;;
    *) echo "Unknown flag: $1"; exit 2 ;;
  esac
done

input.new_string:
# Parse arguments
RUN_LIVE=false
RUN_LAYER=""
RUN_ALL=false
QUIET=false

while [ $# -gt 0 ]; do
  case "$1" in
    --live) RUN_LIVE=true; shift ;;
    --layer) RUN_LAYER="$2"; shift 2 ;;
    --integration) RUN_LAYER="7"; shift ;;
    --all) RUN_ALL=true; RUN_LIVE=true; shift ;;
    --verbose) export VERBOSE=true; shift ;;
    --quiet) QUIET=true; shift ;;
    *) echo "Unknown flag: $1"; exit 2 ;;
  esac
done

# --quiet suppresses all normal stdout. Errors on stderr are preserved.
[ "$QUIET" = "true" ] && exec >/dev/null
